// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // fuzz: actor (as uint160 -> address) and amount to deposit/withdraw
    function testFuzz_property(uint160 rawActor, uint256 depositAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // keep actor nonzero and amount within payable bounds
        address actor = address(rawActor);
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, 1 ether);

        // Deploy an attacker that will re-enter c once during receive()
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund the attacker externally so it can deposit and receive refunds
        vm.deal(address(attacker), depositAmount);

        // Attacker deposits into C by calling deposit() with value
        attacker.depositToC{value: depositAmount}();

        // Now attacker invokes withdrawAll on c; for the correct contract
        // this will clear credit before external call, preventing reentrancy
        // For the mutant, reentrancy during the external call will exploit
        // that credit was not yet zeroed and perform a nested withdraw

        // make the attacker be the msg.sender for the withdrawAll call
        // attacker will forward the withdrawAll call so msg.sender inside C is attacker
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after withdrawAll completes, C.credit(attacker) == 0
        // We read it via the public surface; there is no direct getter for mapping, so
        // we observe by attempting to withdraw again: for correct contract, withdrawAll
        // does nothing (no funds left) and does not send value; for mutant reentrancy may
        // have left credit > 0 so second withdraw would send value.
        // To observe state, we check address(c).balance decreased by exactly depositAmount

        // For correct contract: c balance should be original zero + depositAmount - depositAmount == 0
        // For mutant when reentrancy steals double, c.balance < 0 is impossible, but will be insufficient

        // Assert that address(c).balance == 0 (the correct contract always sends out the full deposit on withdraw)
        assertTrue(address(c).balance == 0);
    }
}

// Attacker contract that first deposits into C, then on receiving funds via C's low-level call
// it re-enters C.withdrawAll exactly once (recursion guard) to exploit if C zeros after call.
contract ReentrantAttacker {
    ReentrancyDAO public c;
    bool private entered;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    // deposit into C with provided msg.value
    function depositToC() external payable {
        // call C.deposit()
        c.deposit{value: msg.value}();
    }

    // Called by test to start the withdrawAll flow as this contract
    function callWithdrawAll() external {
        // call C.withdrawAll() as this contract
        c.withdrawAll();
    }

    // receive will be invoked by C's low-level call; re-enter once
    receive() external payable {
        if (!entered) {
            entered = true;
            // re-enter C.withdrawAll to attempt to withdraw again while original call is in-flight
            // This reentrancy should do nothing on the correct contract because credit was zeroed
            c.withdrawAll();
        }
    }
}
